```javascript
import { MeshBasicNodeMaterial, Mesh } from 'three/webgpu';
import { uv, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  const colors = {
    bg0: 0x0b0b10,
    bg1: 0x14141a,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38
  };

  const textConfig = [
    { text: "NOVA ATELIER / JOURNAL", role: "kicker", x: -3.1, y: 1.7, fontSize: 18, letterSpacing: 0.12 },
    { text: "PRECISION IS", role: "hero", x: -3.1, y: 0.9, fontSize: 124, letterSpacing: -0.015 },
    { text: "A HABIT.", role: "hero", x: -3.1, y: 0.25, fontSize: 124, letterSpacing: -0.015 },
    { text: "Notes from the bench: tolerances, tempering, and the case for slower watchmaking.", role: "body", x: -3.1, y: -0.8, fontSize: 26, letterSpacing: 0, maxWidthPx: 1200 },
    { text: "ISSUE 12 / JULY 2026", role: "caption", x: -3.1, y: -1.9, fontSize: 18, letterSpacing: 0.08 }
  ];

  // Background plane with vertical engineered gradient
  const bgGeo = new THREE.PlaneGeometry(7, 5.5);
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = mix(
    new THREE.Color(colors.bg0),
    new THREE.Color(colors.bg1),
    uv().y
  );

  const bgPlane = new Mesh(bgGeo, bgMat);
  bgPlane.position.z = -0.1;
  group.add(bgPlane);

  // Text meshes and shadows
  const textMeshes = [];
  const shadowMeshes = [];
  const resourcesToDispose = [bgGeo, bgMat];

  for (let i = 0; i < textConfig.length; i++) {
    const cfg = textConfig[i];
    const letterSpacingPx = cfg.fontSize * cfg.letterSpacing;

    // Main text at specified position, offset +0.4 for entrance animation
    const textMesh = ctx.fontAtlas.createText(cfg.text, {
      fontSize: cfg.fontSize,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx,
      ...(cfg.maxWidthPx && { maxWidthPx: cfg.maxWidthPx })
    });

    textMesh.position.set(cfg.x, cfg.y + 0.4, 0);
    textMesh.userData.role = cfg.role;
    textMesh.userData.targetY = cfg.y;

    // Enable transparency for fade animation
    const getMaterial = (obj) => obj.material || (obj.children?.[0]?.material);
    const mat = getMaterial(textMesh);
    if (mat) {
      mat.transparent = true;
      mat.opacity = 0;
    }

    group.add(textMesh);
    textMeshes.push(textMesh);

    // Letterpress shadow: hero glyphs duplicated 0.02 units behind at ink color
    if (cfg.role === 'hero') {
      const shadowText = ctx.fontAtlas.createText(cfg.text, {
        fontSize: cfg.fontSize,
        color: '#16161d',
        align: 'left',
        letterSpacingPx,
        ...(cfg.maxWidthPx && { maxWidthPx: cfg.maxWidthPx })
      });

      shadowText.position.set(cfg.x, cfg.y + 0.4, -0.02);
      group.add(shadowText);
      shadowMeshes.push(shadowText);
    }
  }

  // Accent underline rule: 2.2 × 0.05 units, emissive signal red
  const ruleGeo = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.2
  });

  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(-3.1 + 1.1, -0.15, 0.01);
  ruleMesh.scale.x = 0; // Start hidden, will draw scaleX 0→1
  group.add(ruleMesh);

  resourcesToDispose.push(ruleGeo, ruleMat);

  // === ENTRANCE ANIMATION ===
  const timeline = gsap.timeline();

  // Rise-in per block: y +0.4→0, opacity 0→1, 700ms, staggered 80ms
  textMeshes.forEach((mesh, index) => {
    const delay = index * 0.08;
    const mat = mesh.material || mesh.children?.[0]?.material;

    timeline.to(
      mesh.position,
      { y: mesh.userData.targetY, duration: 0.7, ease: "power3.out" },
      delay
    );

    if (mat) {
      timeline.to(
        mat,
        { opacity: 1, duration: 0.7, ease: "power2.out" },
        delay
      );
    }
  });

  // Shadow text animates with main text
  shadowMeshes.forEach((mesh, index) => {
    const delay = (index + 1) * 0.08; // hero at indices 1, 2
    const targetY = textConfig[index + 1].y;

    timeline.to(
      mesh.position,
      { y: targetY, duration: 0.7, ease: "power3.out" },
      delay
    );
  });

  // Rule draws scaleX 0→1 after hero lands (at ~860ms)
  const ruleDelay = 2 * 0.08 + 0.7; // hero-2 completes
  timeline.to(
    ruleMesh.scale,
    { x: 1, duration: 0.5, ease: "power2.inOut" },
    ruleDelay
  );

  // === CLEANUP ===
  group.userData.cleanup = () => {
    timeline.kill();
    resourcesToDispose.forEach(res => res?.dispose?.());

    const disposeTree = (obj) => {
      obj.geometry?.dispose?.();
      obj.material?.dispose?.();
      obj.children?.forEach(disposeTree);
    };

    textMeshes.forEach(disposeTree);
    shadowMeshes.forEach(disposeTree);
  };

  return group;
}
